static const struct font font_large = {
    .glyphs = glyphs_large,
    .glyph_count = sizeof(glyphs_large) / sizeof(glyphs_large[0]),
    .bitmap = bitmap_large,
    .baseline = 27,
};

const struct font* font_default(void) { return &font_medium; }

const struct font* font_for_size(unsigned size) {
    if (size == 1U)
        return &font_small;
    if (size >= 3U)
        return &font_large;
    return &font_medium;
}

const struct font_glyph* font_lookup(const struct font* font, uint32_t codepoint) {
    size_t first = 0U;
    size_t last = font->glyph_count;
    while (first < last) {
        const size_t middle = first + (last - first) / 2U;
        if (font->glyphs[middle].codepoint == codepoint)
            return &font->glyphs[middle];
        if (font->glyphs[middle].codepoint < codepoint)
            first = middle + 1U;
        else
            last = middle;
    }
    return NULL;
}
